@Override
	public void triggerActiveAbility(Level world, ServerPlayer player, ItemStack stack) {
		if (SuperpositionHandler.hasSpellstoneCooldown(player))
			return;

		CachedTeleportationLocation location = null;

		if (this.locationCache.containsKey(player)) {
			try {
				var future = this.locationCache.get(player);

				if (future.isDone()) {
					location = this.locationCache.get(player).get();
				} else {
					future.cancel(true);
				}

				this.locationCache.remove(player);
			} catch (Exception ex) {
				ex.printStackTrace();
			}
		}

		if (location == null) {
			EnigmaticLegacy.LOGGER.getInternal().info("No cached location found for {}, generating new one synchronously.", player.getGameProfile().getName());
			location = this.findRandomLocation(player);
		}

		ResourceKey<Level> key = location.dimension();

		world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
		EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketRecallParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 48, false));
		player.teleportTo(location.x(), location.y(), location.z());

		if (player.level().dimension() != key) {
			SuperpositionHandler.sendToDimension(player, key);
			player.teleportTo(location.x(), location.y(), location.z());
		}

		world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
		EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketRecallParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 48, false));

		SuperpositionHandler.setSpellstoneCooldown(player, this.getCooldown(player));

		EnigmaticLegacy.LOGGER.getInternal().info("Player {} triggered active ability of Non-Euclidean Cube. Teleported to D: {}, X: {}, Y: {}, Z: {}.",
				player.getGameProfile().getName(), player.level().dimension(), player.getX(), player.getY(), player.getZ());
	}

@Override
	public void curioTick(SlotContext context, ItemStack stack) {
		if (context.entity() instanceof Player player) {
			if (player.getAirSupply() < 300) {
				player.setAirSupply(300);
			}

			if (player.isOnFire()) {
				player.clearFire();
			}

			AttributeMap map = player.getAttributes();
			map.addTransientAttributeModifiers(this.getCurrentModifiers(player));

			if (context.entity() instanceof ServerPlayer) {
				if (!this.locationCache.containsKey(player)) {
					this.generateCachedLocation((ServerPlayer) player);
				} else {
					Future<CachedTeleportationLocation> future = this.locationCache.get(player);

					if (future.isDone() && !future.isCancelled()) {
						try {
							CachedTeleportationLocation location = future.get();

							if (location.dimension() == player.level().dimension()) {
								this.generateCachedLocation((ServerPlayer) player);
							}
						} catch (Exception ex) {
							throw new RuntimeException(ex);
						}
					}
				}
			}
		}
	}

@Override
	public void onUnequip(SlotContext context, ItemStack newStack, ItemStack stack) {
		if (context.entity() instanceof Player player) {
			AttributeMap map = player.getAttributes();
			map.removeAttributeModifiers(this.getCurrentModifiers(player));
		}
	}

private void generateCachedLocation(ServerPlayer player) {
		Future<CachedTeleportationLocation> future = this.executor.submit(() -> {
			try {
				CachedTeleportationLocation location = this.findRandomLocation(player);
				EnigmaticLegacy.LOGGER.debug("Found random location: " + location);
				return location;
			} catch (Exception ex) {
				EnigmaticLegacy.LOGGER.error("Could not find random location for:" + player.getGameProfile().getName());
				ex.printStackTrace();
				throw ex;
			}
		});

		this.locationCache.put(player, future);
	}

private CachedTeleportationLocation findRandomLocation(ServerPlayer player) {
		ResourceKey<Level> key = SuperpositionHandler.getRandomElement(this.worlds, player.level().dimension());
		ServerLevel level = SuperpositionHandler.getWorld(key);

		if (level == null) {
			EnigmaticLegacy.LOGGER.error("Could not find world: " + key);
			EnigmaticLegacy.LOGGER.error("This is never supposed to happen!");
			key = Level.OVERWORLD;
			level = SuperpositionHandler.getOverworld();
		}

		int border = (int) level.getWorldBorder().getSize() / 2;
		int attempts = 0;
		int radius = border < 10000 ? border : 10000;

		while (true) {
			BlockPos pos = new BlockPos(radius - random.nextInt(radius * 2), key == Level.NETHER ? 100 : 200, radius - random.nextInt(radius * 2));
			level.getChunkAt(pos);

			for (int i = 0; i < 4; i++) {
				if (i > 0) {
					pos = new BlockPos((pos.getX() >> 4) * 16 + random.nextInt(16), pos.getY(), (pos.getZ() >> 4) * 16 + random.nextInt(16));
				}

				var location = this.findValidPosition(player, level, pos.getX(), pos.getY(), pos.getZ());

				if (!location.isEmpty())
					return new CachedTeleportationLocation(key, location.get().x, location.get().y, location.get().z);
			}

			if (++attempts > 100)
				return this.findRandomLocation(player);
		}
	}

private Optional<Vector3> findValidPosition(ServerPlayer player, Level world, int x, int y, int z) {
		int checkAxis = y - 10;

		for (int counter = 0; counter <= checkAxis; counter++) {
			BlockPos below = new BlockPos(x, y - counter - 1, z);
			BlockPos feet = new BlockPos(x, y - counter, z);
			BlockPos head = new BlockPos(x, y - counter + 1, z);

			if (world.getMinBuildHeight() >= below.getY())
				return Optional.empty();

			if (!world.isEmptyBlock(below) && world.getBlockState(below).canOcclude() && world.isEmptyBlock(feet) && world.isEmptyBlock(head))
				return Optional.of(new Vector3(feet.getX() + 0.5, feet.getY(), feet.getZ() + 0.5));
		}

		return Optional.empty();
	}

public void clearLocationCache() {
		this.locationCache.clear();
	}

public boolean tick() {
			// If empty, this swapper is done.
			if (candidateQueue.isEmpty()) {
				return false;
			}

			int remainingSwaps = BLOCK_SWAP_RATE;
			while (remainingSwaps > 0 && !candidateQueue.isEmpty()) {
				SwapCandidate cand = candidateQueue.poll();

				// If we've already completed this location, move along, as this
				// is just a suboptimal one.
				if (completedCoords.contains(cand.coordinates)) {
					continue;
				}

				// If this candidate is out of range, discard it.
				if (cand.range <= 0) {
					continue;
				}

				// Otherwise, perform the break and then look at the adjacent tiles.
				ToolCommons.removeBlockWithDrops(player, truncator, world,
						cand.coordinates,
						state -> state.is(BlockTags.MINEABLE_WITH_AXE) || state.is(BlockTags.LEAVES));

				remainingSwaps--;

				completedCoords.add(cand.coordinates);

				// Then, go through all of the adjacent blocks and look if
				// any of them are any good.
				for (BlockPos adj : adjacent(cand.coordinates)) {
					var state = world.getBlockState(adj);

					boolean isWood = state.is(BlockTags.LOGS);
					boolean isLeaf = state.is(BlockTags.LEAVES);
					// TODO: Make "blocks the axe will propagate through" a tag
					boolean shouldPropagateThrough = isWood || isLeaf
							|| state.is(Blocks.MANGROVE_ROOTS);

					if (!shouldPropagateThrough) {
						continue;
					}

					// If this is a leaf, it gets
					// the minimum of the leaf range and the current range - 1.
					// Otherwise, it gets the standard range - 1.
					int newRange = isLeaf ? Math.min(LEAF_BLOCK_RANGE, cand.range - 1) : cand.range - 1;

					candidateQueue.offer(new SwapCandidate(adj, newRange));
				}
			}

			// If we did any iteration, then hang around until next tick.
			return true;
		}

public static boolean shouldBreak(Player player) {
		return !player.isShiftKeyDown() && !StoneOfTemperanceItem.hasTemperanceActive(player);
	}

@SoftImplement("IForgeItem")
	public boolean onBlockStartBreak(ItemStack stack, BlockPos pos, Player player) {
		BlockHitResult raycast = ToolCommons.raytraceFromEntity(player, 10, false);
		if (raycast.getType() == HitResult.Type.BLOCK) {
			Direction face = raycast.getDirection();
			breakOtherBlock(player, stack, pos, pos, face);
			if (player.isSecondaryUseActive()) {
				BotaniaAPI.instance().breakOnAllCursors(player, stack, pos, face);
			}
		}

		return false;
	}

@Override
	public void breakOtherBlock(Player player, ItemStack stack, BlockPos pos, BlockPos originPos, Direction side) {
		if (shouldBreak(player) && !tickingSwappers) {
			addBlockSwapper(player.level(), player, stack, pos);
		}
	}

public static void onTickEnd(ServerLevel world) {
		ResourceKey<Level> dim = world.dimension();
		if (blockSwappers.containsKey(dim)) {
			tickingSwappers = true;
			Set<BlockSwapper> swappers = blockSwappers.get(dim);

			// Iterate through all of our swappers, removing any
			// which no longer need to tick.
			swappers.removeIf(next -> next == null || !next.tick());
			tickingSwappers = false;
		}
	}

private static void addBlockSwapper(Level world, Player player, ItemStack stack, BlockPos origCoords) {
		// Block swapper registration should only occur on the server
		if (world.isClientSide) {
			return;
		}

		BlockSwapper swapper = new BlockSwapper(world, player, stack, origCoords, TerraTruncatorItem.BLOCK_RANGE);

		ResourceKey<Level> dim = world.dimension();
		blockSwappers.computeIfAbsent(dim, d -> new HashSet<>()).add(swapper);
	}

public List<BlockPos> adjacent(BlockPos original) {
			List<BlockPos> coords = new ArrayList<>();
			// Visit all the surrounding blocks in the provided radius.
			// Gotta love these nested loops, right?
			for (int dx = -SINGLE_BLOCK_RADIUS; dx <= SINGLE_BLOCK_RADIUS; dx++) {
				for (int dy = -SINGLE_BLOCK_RADIUS; dy <= SINGLE_BLOCK_RADIUS; dy++) {
					for (int dz = -SINGLE_BLOCK_RADIUS; dz <= SINGLE_BLOCK_RADIUS; dz++) {
						// Skip the central tile.
						if (dx == 0 && dy == 0 && dz == 0) {
							continue;
						}

						coords.add(original.offset(dx, dy, dz));
					}
				}
			}

			return coords;
		}

public static void removeBlockWithDrops(Player player, ItemStack stack, Level world, BlockPos pos,
			Predicate<BlockState> filter) {
		if (!world.hasChunkAt(pos)) {
			return;
		}

		BlockState blockstate = world.getBlockState(pos);
		boolean unminable = blockstate.getDestroyProgress(player, world, pos) == 0;

		if (!world.isClientSide && !unminable && filter.test(blockstate) && !blockstate.isAir()) {
			ItemStack save = player.getMainHandItem();
			player.setItemInHand(InteractionHand.MAIN_HAND, stack);
			((ServerPlayer) player).connection.send(
					new ClientboundLevelEventPacket(LevelEvent.PARTICLES_DESTROY_BLOCK, pos, Block.getId(blockstate), false));
			((ServerPlayer) player).gameMode.destroyBlock(pos);
			player.setItemInHand(InteractionHand.MAIN_HAND, save);
		}
	}

@SubscribeEvent
        public static void onLivingDamageModifiers(LivingDamageEvent.Pre event) {
            var target = event.getEntity();
            var source = event.getSource().getEntity();

            if (!target.level().isClientSide() && target.getPersistentData().getLong(FOG_SUFFOCATION_UNTIL_TAG) >= target.level().getGameTime()
                    && event.getSource().is(DamageTypes.IN_WALL)) {
                var modifier = target.getPersistentData().getFloat(FOG_SUFFOCATION_DAMAGE_TAG);

                event.setNewDamage((float) (event.getNewDamage() * (1D + modifier)));
            }

            if (!target.level().isClientSide()) {
                var targetId = target.getStringUUID();

                for (var player : target.level().players()) {
                    for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.GHOSTLY_MANTLE.get())) {
                        var relic = (GhostlyMantleItem) stack.getItem();
                        var marks = relic.getReprisalMarks(stack);
                        var modifier = marks.remove(targetId);

                        if (modifier == null)
                            continue;

                        var original = event.getNewDamage();
                        var modified = original * (1D + modifier);
                        var extra = modified - original;

                        event.setNewDamage((float) modified);
                        relic.setReprisalMarks(stack, marks);

                        var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("spectral_escape");

                        ability.getStatisticData().getMetricData("reprisal_damage").addValue(extra);

                        if (extra > 0D) {
                            var experience = player.getRandom().nextInt((int) (extra + 1D));

                            if (experience > 0)
                                relic.getRelicData(player, stack).getLevelingData().addExperience("spectral_escape", "reprisal_damage", experience);
                        }

                        return;
                    }
                }
            }

            if (!(target instanceof Player player) || !(source instanceof LivingEntity attacker) || source == target)
                return;

            for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.GHOSTLY_MANTLE.get())) {
                var relic = (GhostlyMantleItem) stack.getItem();
                var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("gaze");

                if (!ability.canPlayerUse(player))
                    continue;

                var data = relic.getGazeCharges(stack).get(attacker.getStringUUID());

                if (data == null || data.charges() <= 0)
                    continue;

                var original = event.getNewDamage();
                var reduction = data.charges() * ability.getStatData("weakness").getValue();

                event.setNewDamage((float) Math.max(0D, original * (1D - reduction)));
                ability.getStatisticData().getMetricData("damage_reduced").addValue(original - event.getNewDamage());

                return;
            }
        }

@Override
    public void curioTick(SlotContext slotContext, ItemStack stack) {
        super.curioTick(slotContext, stack);

        var entity = slotContext.entity();

        if (entity.level().isClientSide())
            return;

        this.tickFogTrail(entity, stack);
        this.tickGaze(entity, stack);

        if (this.getEscapeCooldown(stack) > 0)
            this.setEscapeCooldown(stack, this.getEscapeCooldown(stack) - 1);

        var spectralEscape = this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("spectral_escape");

        if (spectralEscape.canPlayerUse(entity)
                && entity.hasEffect(RelicsMobEffects.FLIGHT)
                && entity.hasEffect(RelicsMobEffects.IMMORTALITY)) {
            spectralEscape.getStatisticData().getMetricData("spectral_form_duration").addValue(1D / 20D);
            this.getRelicData(entity, stack).getLevelingData().addExperience("spectral_escape", "spectral_form", 1D / 20D);
        }
    }

private void tickFogTrail(LivingEntity entity, ItemStack stack) {
        var ability = this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("fog");

        if (!ability.canPlayerUse(entity) || ability.getMode().equals("disabled")) {
            this.setLastFogPos(stack, entity.position());

            return;
        }

        var current = entity.position();
        var last = this.getLastFogPos(stack);

        if (last == Vec3.ZERO || last.distanceToSqr(current) > 256D) {
            this.setLastFogPos(stack, current);

            return;
        }

        var distance = last.distanceTo(current);
        var fogRadius = Math.max(0.1D, ability.getStatData("radius").getValue());

        if (distance < fogRadius)
            return;

        var direction = current.subtract(last).normalize();
        var steps = Math.min(8, (int) Math.floor(distance / fogRadius));
        var gravity = entity.getAttributeValue(Attributes.GRAVITY);
        var maxGroundSearch = FOG_GROUND_SEARCH_STEP;

        if (gravity > 0.001D) {
            var upwardSpeed = entity.getAttributeValue(Attributes.JUMP_STRENGTH);

            while (upwardSpeed > 0D && maxGroundSearch < MAX_FOG_GROUND_SEARCH) {
                maxGroundSearch += upwardSpeed;
                upwardSpeed = (upwardSpeed - gravity) * 0.98D;
            }

            maxGroundSearch = Math.min(maxGroundSearch, MAX_FOG_GROUND_SEARCH);
        }

        var spawned = false;

        for (var i = 1; i <= steps; i++) {
            var pos = last.add(direction.scale(i * fogRadius));
            var y = pos.y;
            var groundFound = false;

            for (var j = 0D; j <= maxGroundSearch; j += FOG_GROUND_SEARCH_STEP) {
                var blockPos = BlockPos.containing(pos.x, pos.y + 0.2D - j, pos.z);
                var state = entity.level().getBlockState(blockPos);

                if (state.isAir())
                    continue;

                var shape = state.getCollisionShape(entity.level(), blockPos);

                if (shape.isEmpty())
                    continue;

                y = blockPos.getY() + shape.max(Direction.Axis.Y) + 0.03D;
                groundFound = true;

                break;
            }

            if (!groundFound)
                continue;

            var fog = new GhostlyFogEntity(RelicsEntities.GHOSTLY_FOG.get(), entity.level());

            fog.setOwner(entity);
            fog.setLifetime((int) Math.max(1D, ability.getStatData("duration").getValue() * 20D));
            fog.setRadius((float) fogRadius);
            fog.setAirDrain((int) Math.max(0D, MathUtils.round(ability.getStatData("air_loss").getValue(), 0)));
            fog.setSuffocationDamage((float) ability.getStatData("suffocation_damage").getValue());
            fog.setTremorTicks(ability.getRankModifierData("frostbite").isEnabled() ? (int) Math.max(1D, ability.getStatData("tremor").getValue() * 20D) : 0);
            fog.setStack(stack);
            fog.setPos(pos.x, y, pos.z);

            entity.level().addFreshEntity(fog);
            spawned = true;

            ability.getStatisticData().getMetricData("fog_clouds").addValue(1);
            this.getRelicData(entity, stack).getLevelingData().addExperience("fog", "fog_creation", 0.1D / steps);
        }

        this.setLastFogPos(stack, spawned ? last.add(direction.scale(steps * fogRadius)) : current);
    }

private void tickGaze(LivingEntity owner, ItemStack stack) {
        var ability = this.getRelicData(owner, stack).getAbilitiesData().getAbilityData("gaze");
        var charges = this.getGazeCharges(stack);
        var changed = false;

        if (!ability.canPlayerUse(owner)) {
            if (!charges.isEmpty()) {
                charges.clear();
                this.setGazeCharges(stack, charges);
            }

            return;
        }

        var seenThisTick = new java.util.HashSet<String>();
        var range = ability.getStatData("range").getValue();
        var maxCharges = Math.max(1, (int) MathUtils.round(ability.getStatData("charges").getValue(), 0));

        for (var target : owner.level().getEntitiesOfClass(LivingEntity.class, owner.getBoundingBox().inflate(range),
                entity -> entity != owner && entity.isAlive() && TargetingUtils.canHarm(owner, entity, stack, "gaze"))) {
            var key = target.getStringUUID();
            var looking = isLookingAt(target, owner) && target.hasLineOfSight(owner);
            var data = charges.getOrDefault(key, GazeChargeData.EMPTY);

            if (!looking)
                continue;

            seenThisTick.add(key);

            var lookTicks = data.lookTicks() + 1;
            var currentCharges = data.charges();

            if (lookTicks >= 20) {
                lookTicks = 0;

                if (currentCharges < maxCharges) {
                    currentCharges++;
                    ability.getStatisticData().getMetricData("charges_applied").addValue(1);
                    this.getRelicData(owner, stack).getLevelingData().addExperience("gaze", "eye_contact", 1);
                }
            }

            charges.put(key, new GazeChargeData(currentCharges, lookTicks, 0));
            changed = true;
        }

        var iterator = charges.entrySet().iterator();

        while (iterator.hasNext()) {
            var entry = iterator.next();

            if (seenThisTick.contains(entry.getKey()))
                continue;

            var data = entry.getValue();
            var decayTicks = data.decayTicks() + 1;
            var currentCharges = data.charges();

            if (decayTicks >= 20) {
                decayTicks = 0;
                currentCharges--;
            }

            if (currentCharges <= 0)
                iterator.remove();
            else
                entry.setValue(new GazeChargeData(currentCharges, 0, decayTicks));

            changed = true;
        }

        if (changed)
            this.setGazeCharges(stack, charges);
    }

private static boolean isLookingAt(LivingEntity watcher, LivingEntity target) {
        var toTarget = target.getEyePosition().subtract(watcher.getEyePosition());

        if (toTarget.lengthSqr() <= 1.0E-6D)
            return false;

        var look = watcher.getLookAngle().normalize();
        var direction = toTarget.normalize();

        return look.dot(direction) > 0.85D;
    }

@SubscribeEvent
        public static void onLivingDeath(LivingDeathEvent event) {
            var target = event.getEntity();

            if (target.level().isClientSide())
                return;

            if (!(target instanceof Player player))
                return;

            for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.GHOSTLY_MANTLE.get())) {
                var relic = (GhostlyMantleItem) stack.getItem();
                var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("spectral_escape");

                if (!ability.canPlayerUse(player) || relic.getEscapeCooldown(stack) > 0)
                    continue;

                event.setCanceled(true);

                player.setHealth(Math.max(1F, player.getHealth()));
                player.deathTime = 0;

                var duration = (int) Math.max(1D, ability.getStatData("duration").getValue() * 20D);

                player.addEffect(new MobEffectInstance(RelicsMobEffects.FLIGHT, duration, 0, false, false, true));
                player.addEffect(new MobEffectInstance(RelicsMobEffects.IMMORTALITY, duration, 0, false, false, true));
                relic.setEscapeCooldown(stack, (int) Math.max(1D, ability.getStatData("cooldown").getValue() * 20D));

                ability.getStatisticData().getMetricData("prevented_deaths").addValue(1);

                var leveling = relic.getRelicData(player, stack).getLevelingData();
                var experience = leveling.getTotalExperienceBetweenLevels(leveling.getLevel(), leveling.getLevel() + 1) * 0.05D;

                relic.getRelicData(player, stack).getLevelingData().addExperience("spectral_escape", "death_prevention", experience);

                if (ability.getRankModifierData("reprisal").isEnabled() && event.getSource().getEntity() instanceof LivingEntity attacker && attacker != player
                        && TargetingUtils.canHarm(player, attacker, stack, "spectral_escape")) {
                    var marks = relic.getReprisalMarks(stack);

                    marks.put(attacker.getStringUUID(), ability.getStatData("damage").getValue());
                    relic.setReprisalMarks(stack, marks);
                }

                return;
            }
        }

@SubscribeEvent
        public static void onLivingDamage(LivingDamageEvent.Pre event) {
            if (!(event.getSource().getEntity() instanceof Player player))
                return;

            for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.GHOSTLY_MANTLE.get())) {
                var relic = (GhostlyMantleItem) stack.getItem();
                var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("gaze");

                if (!ability.canPlayerUse(player) || !ability.getRankModifierData("dread").isEnabled())
                    continue;

                if (!TargetingUtils.canHarm(player, event.getEntity(), stack, "gaze"))
                    continue;

                var charges = relic.getTotalCharges(stack);

                if (charges <= 0)
                    continue;

                var extra = event.getNewDamage() * charges * ability.getStatData("damage").getValue();

                event.setNewDamage((float) (event.getNewDamage() + extra));
                ability.getStatisticData().getMetricData("damage_bonus").addValue(extra);

                return;
            }
        }

public Map<String, Double> getReprisalMarks(ItemStack stack) {
        return new HashMap<>(stack.getOrDefault(RelicsDataComponents.GHOSTLY_MANTLE_REPRISAL_MARKS, Map.of()));
    }

public void setReprisalMarks(ItemStack stack, Map<String, Double> marks) {
        stack.set(RelicsDataComponents.GHOSTLY_MANTLE_REPRISAL_MARKS, new HashMap<>(marks));
    }

public int getEscapeCooldown(ItemStack stack) {
        return stack.getOrDefault(RelicsDataComponents.GHOSTLY_MANTLE_ESCAPE_COOLDOWN, 0);
    }

public void setEscapeCooldown(ItemStack stack, int cooldown) {
        stack.set(RelicsDataComponents.GHOSTLY_MANTLE_ESCAPE_COOLDOWN, Math.max(0, cooldown));
    }

@Override
    public void tick() {
        super.tick();

        this.setDeltaMovement(0D, 0D, 0D);

        if (this.level().isClientSide()) {
            if (this.getLifetime() - this.tickCount > 1) {
                var random = this.random;
                var radius = this.getRadius();

                var x = this.getX() + MathUtils.randomFloat(random) * radius;
                var z = this.getZ() + MathUtils.randomFloat(random) * radius;

                this.level().addParticle(new GhostlyFogParticle.Options(this.getLifetime() - this.tickCount - 1),
                        x,
                        this.getY() + random.nextDouble() * 2,
                        z,
                        MathUtils.randomFloat(random) * 0.01F,
                        -0.025F,
                        MathUtils.randomFloat(random) * 0.01F);
            }

            return;
        }

        if (this.tickCount > this.getLifetime()) {
            this.discard();

            return;
        }

        var owner = this.getOwner();
        var radius = this.getRadius();
        var gameTime = this.level().getGameTime();

        if (lastExposureCleanupTick != gameTime && gameTime % 200L == 0L) {
            lastExposureCleanupTick = gameTime;

            LAST_EXPOSURE_TICK.values().removeIf(tick -> tick < gameTime - 200L);
        }

        for (var target : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(radius),
                entity -> entity != owner && entity.isAlive() && TargetingUtils.canHarm(owner, entity, this.getStack(), "fog"))) {
            target.getPersistentData().putFloat(GhostlyMantleItem.FOG_SUFFOCATION_DAMAGE_TAG, this.getSuffocationDamage());
            target.getPersistentData().putLong(GhostlyMantleItem.FOG_SUFFOCATION_UNTIL_TAG, this.level().getGameTime() + 5L);

            if (this.getAirDrain() > 0)
                target.setAirSupply(Math.max(-20, target.getAirSupply() - this.getAirDrain()));

            if (this.getTremorTicks() > 0)
                TargetingUtils.addHarmfulEffect(target, new MobEffectInstance(RelicsMobEffects.TREMOR, this.getTremorTicks(), 0, false, false), owner, this.getStack(), "fog");

            if (target.getAirSupply() <= -20 && this.tickCount % 20 == 0)
                target.hurt(this.level().damageSources().inWall(), 1F);

            if (owner == null)
                continue;

            var key = owner.getStringUUID() + ":" + target.getStringUUID();

            if (LAST_EXPOSURE_TICK.getOrDefault(key, Long.MIN_VALUE) == gameTime)
                continue;

            LAST_EXPOSURE_TICK.put(key, gameTime);

            for (var stack : EntityUtils.findEquippedCurios(owner, RelicsItems.GHOSTLY_MANTLE.get())) {
                var relic = (GhostlyMantleItem) stack.getItem();
                var ability = relic.getRelicData(owner, stack).getAbilitiesData().getAbilityData("fog");

                if (!ability.canPlayerUse(owner))
                    continue;

                ability.getStatisticData().getMetricData("fog_exposure").addValue(1D / 20D);
                relic.getRelicData(owner, stack).getLevelingData().addExperience("fog", "fog_exposure", 1D / 20D);

                break;
            }
        }
    }

@Nullable
    public LivingEntity getOwner() {
        var ownerId = this.getEntityData().get(OWNER_ID);
        var entity = ownerId >= 0 ? this.level().getEntity(ownerId) : null;

        if (entity instanceof LivingEntity owner) {
            if (!this.level().isClientSide())
                this.ownerUuid = owner.getUUID();

            return owner;
        }

        if (this.level().isClientSide() || this.ownerUuid == null || !(this.level() instanceof ServerLevel serverLevel))
            return null;

        var uuidEntity = serverLevel.getEntity(this.ownerUuid);

        if (uuidEntity instanceof LivingEntity owner) {
            this.getEntityData().set(OWNER_ID, owner.getId());

            return owner;
        }

        return null;
    }

@Override
    protected void readAdditionalSaveData(CompoundTag tag) {
        this.setLifetime(tag.getInt("lifetime"));
        this.setRadius(tag.getFloat("radius"));
        this.setAirDrain(tag.getInt("airDrain"));
        this.setSuffocationDamage(tag.getFloat("suffocationDamage"));
        this.setTremorTicks(tag.getInt("tremorTicks"));

        if (tag.hasUUID("owner"))
            this.ownerUuid = tag.getUUID("owner");

        this.setStack(ItemStack.parseOptional(this.registryAccess(), tag.getCompound("stack")));
    }

@Override
    protected void addAdditionalSaveData(CompoundTag tag) {
        tag.putInt("lifetime", this.getLifetime());
        tag.putFloat("radius", this.getRadius());
        tag.putInt("airDrain", this.getAirDrain());
        tag.putFloat("suffocationDamage", this.getSuffocationDamage());
        tag.putInt("tremorTicks", this.getTremorTicks());

        if (this.ownerUuid != null)
            tag.putUUID("owner", this.ownerUuid);

        tag.put("stack", this.getStack().saveOptional(this.registryAccess()));
    }

public void use(int hammerLevel, float hammerEfficiency, float angle) {
        ServerLevel serverLevel = (ServerLevel) getLevel();
        int count = 4 + (int) hammerEfficiency / 4;
        double cone = (20 + hammerLevel * 6) * Math.PI / 180;
        int ox = SectionPos.blockToSectionCoord(getBlockPos().getX());
        int oz = SectionPos.blockToSectionCoord(getBlockPos().getZ());

        int preResultSize = scanResults.size();
        AtomicInteger stagger = new AtomicInteger();

        ChunkPos.rangeClosed(new ChunkPos(-32, -32), new ChunkPos(32, 32))
                .filter(pos -> Math.abs(Mth.atan2(pos.x, pos.z) - angle) < cone)
                .sorted(Comparator.comparingInt(pos -> pos.x * pos.x + pos.z * pos.z))
                .map(pos -> new ChunkPos(pos.x + ox, pos.z + oz))
                .filter(pos -> Math.abs(pos.x - ox) + Math.abs(pos.z - oz) < 20)
                .filter(pos -> scanResults.stream().noneMatch(result -> result.chunkX == pos.x && result.chunkZ == pos.z))
                .limit(count)
                .forEach(pos -> {
//                    boolean wasLoaded = serverLevel.hasChunk(pos.x, pos.z);
//                    System.out.println("has chunk [" + pos.x + ", " + pos.z + "]: " + wasLoaded);
//                    serverLevel.getChunkSource().getGenerator().findNearestMapStructure()
                    long timestamp = this.getTimestamp(serverLevel.getGameTime(), pos.x - ox, pos.z - oz) + stagger.getAndIncrement() * 3L;
                    int height = serverLevel.getChunk(pos.x, pos.z, ChunkStatus.SURFACE).getHeight(Heightmap.Types.WORLD_SURFACE_WG, pos.x, pos.z);

                    BlockPos centerPos = pos.getMiddleBlockPosition(height);
                    float temperature = level.getBiome(centerPos).value().getTemperature(centerPos);
                    List<String> structures =
                            Arrays.stream(getScannableStructures())
                                    .filter(id -> ScanHelper.hasStructure(id, serverLevel, pos)).toList();
                    scanResults.add(new ScanResult(pos.x, pos.z, height, temperature, structures, timestamp));


//                    if (!wasLoaded) {
//                        System.out.println("[post]  Was not loaded, is now: " + serverLevel.hasChunk(pos.x, pos.z));
//                        ServerScheduler.schedule(100, () -> System.out.println("[delayed] Was not loaded, is now: " + serverLevel.hasChunk(pos.x, pos.z)));
//                    }


                    ServerScheduler.schedule((int) ((timestamp - serverLevel.getGameTime())), () ->
                            serverLevel.playSound(null, getBlockPos(), TetraSounds.scanMiss, SoundSource.PLAYERS, 0.01f, 1.0f + (float) Math.random() * 0f));
                    if (!structures.isEmpty()) {
                        ServerScheduler.schedule((int) ((timestamp - serverLevel.getGameTime()) + 20), () ->
                                serverLevel.playSound(null, getBlockPos(), TetraSounds.scanHit, SoundSource.PLAYERS, 0.1f, 1.0f));
                    }

                });

        if (preResultSize != scanResults.size()) {
            setChanged();
            level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), 3);
        }
    }

private long getTimestamp(long gametime, int x, int y) {
        return (long) (gametime + (Mth.length(x, y) * 1.5) + Math.random() * 5);
    }

public void toggleScanMode(boolean enable) {
        long diff = Math.abs(Math.abs(scanModeTimestamp) - level.getGameTime());
        long time = diff < 5 ? level.getGameTime() - diff : level.getGameTime();
        scanModeTimestamp = enable ? time : -time;

        setChanged();
        level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), 3);
    }

@Override
    public void load(CompoundTag compound) {
        super.load(compound);

        itemTag = compound.getCompound("item");

        scanModeTimestamp = compound.getLong("timestamp");

        scanResults = compound.getList("scan", Tag.TAG_COMPOUND).stream()
                .map(nbt -> ScanResult.codec.decode(NbtOps.INSTANCE, nbt))
                .map(DataResult::result)
                .filter(Optional::isPresent)
                .map(Optional::get)
                .map(Pair::getFirst)
                .collect(Collectors.toCollection(ArrayList::new));
    }

@Override
    public void saveAdditional(CompoundTag compound) {
        super.saveAdditional(compound);

        compound.put("item", itemTag);

        compound.putLong("timestamp", scanModeTimestamp);

        ListTag list = scanResults.stream()
                .map(scroll -> ScanResult.codec.encodeStart(NbtOps.INSTANCE, scroll))
                .map(DataResult::result)
                .filter(Optional::isPresent)
                .map(Optional::get)
                .collect(Collectors.toCollection(ListTag::new));
        compound.put("scan", list);
    }

public static void schedule(int delay, Runnable task) {
        queue.add(new Task(counter + delay, task));
    }

@SubscribeEvent
    public static void onServerTick(TickEvent.ServerTickEvent event) {
        if (event.phase != TickEvent.Phase.END) {
            return;
        }

        for (Iterator<Task> it = queue.iterator(); it.hasNext(); ) {
            Task task = it.next();
            if (task.getTick() < counter) {
                task.run();
                it.remove();
            }
        }

        counter++;
    }
